package ru.hive13.server;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import ru.hive13.model.*;
import static ru.hive13.model.Model.*;
import java.util.*;

class ReferenceGeometryTest {
    @Test void biomassAlarmRequiresMeasuredGrowthAndPoweredSensor(){var e=new GameEngine(WorldFactory.create("STORY"));for(var a:e.state.actors){a.connected=true;a.ready=true;}e.start();e.state.creatures.clear();e.state.gameTime=20;e.state.rooms.get("B3").biomass=1;e.state.rooms.get("B4").biomass=64.98;e.state.triggeredEvents.add("biomass_alert");e.state.progress.put("sensor:biomass:B4",64d);e.advance(.3);assertEquals(0,e.state.events.stream().filter(v->v.text.contains("биомасса 64%")).count());e.advance(.4);assertEquals(1,e.state.events.stream().filter(v->v.text.contains("биомасса 64% → 65%")).count());e.state.rooms.get("B3").powered=false;e.state.rooms.get("B4").biomass=65.99;e.advance(1);assertEquals(65,e.state.progress.get("sensor:biomass:B4"));e.state.rooms.get("B3").powered=true;e.advance(.1);assertEquals(1,e.state.events.stream().filter(v->v.text.contains("биомасса 65% → 66%")).count());}
    @Test void allRoomAnchorsAndDoorPortsAreNavigable(){var s=WorldFactory.create("STORY");for(var r:s.rooms.values())assertTrue(r.contains(r.center().x(),r.center().y()),r.id+" center");for(var d:s.doors.values()){assertTrue(s.rooms.get(d.a).contains(d.pa.x(),d.pa.y()),d.id+" A port");assertTrue(s.rooms.get(d.b).contains(d.pb.x(),d.pb.y()),d.id+" B port");assertEquals(d.pa.distance(d.pb),d.pa.distance(d.center())+d.center().distance(d.pb),.001,d.id+" gate lies on corridor");}}
    @Test void notchedRoomsRejectTheirEmptyBoundingBoxCorners(){var s=WorldFactory.create("STORY");assertFalse(s.rooms.get("A1").contains(95,195));assertTrue(s.rooms.get("A1").contains(155,202));assertFalse(s.rooms.get("B7").contains(400,400));assertTrue(s.rooms.get("B7").contains(410,337));assertFalse(s.rooms.get("B2").contains(Double.NaN,120));}
    @Test void localMovementRoutesAroundNotchedWalls(){var s=WorldFactory.create("STORY");var room=s.rooms.get("A1");Point start=new Point(88,230),goal=new Point(180,183);assertFalse(Pathfinder.segmentInside(room,start,goal));var route=Pathfinder.find(s,"A1",start,"A1",goal);assertNotNull(route);assertTrue(route.points().size()>1);var p=start;for(var next:route.points()){assertTrue(Pathfinder.segmentInside(room,p,next));p=next;}assertEquals(goal,p);}
    @Test void everyRoomRouteStaysOnActualFloorOrDoorCorridor(){var s=WorldFactory.create("STORY");s.doors.values().forEach(d->d.status=DoorStatus.OPEN);for(var from:s.rooms.values())for(var to:s.rooms.values()){var route=Pathfinder.find(s,from.id,from.center(),to.id,to.center());assertNotNull(route,from.id+" → "+to.id);var p=from.center();for(var next:route.points()){for(int i=0;i<=50;i++){var sample=p.lerp(next,i/50d);assertFalse(Pathfinder.ownerAt(s,sample.x(),sample.y()).isEmpty(),from.id+" → "+to.id+" outside at "+sample);}p=next;}}}
    @Test void changingDestinationInsideDoorCorridorRemainsContinuous(){var s=WorldFactory.create("STORY");var d=s.doors.get("D13");d.status=DoorStatus.OPEN;var start=new Point(751,275);var route=Pathfinder.find(s,"C1",start,"B5",s.rooms.get("B5").center());assertNotNull(route);assertEquals(d.pa,route.points().getFirst());}
    @Test void corridorOwnershipChangesAtActualGate(){var s=WorldFactory.create("STORY");var d=s.doors.get("D13");assertEquals("C1",Pathfinder.ownerAt(s,d.center().x()-1,d.center().y()));assertEquals("C2",Pathfinder.ownerAt(s,d.center().x()+1,d.center().y()));}
    @Test void migrationPreservesCampaignAndReanchorsDoorWaypoints(){var s=WorldFactory.create("STORY");s.layoutRevision=1;s.rooms.put("A2",new Room("A2","МЕДБЛОК",185,205,120,100));s.rooms.put("B2",new Room("B2","СИЛОВОЙ БЛОК",170,45,125,120));var old=new Door("D06","A2","B2",new Point(240,205),new Point(240,165),DoorStatus.CLOSED);s.doors.put(old.id,old);var a=s.actor(0);a.x=245;a.y=255;a.hp=71;a.path=new ArrayList<>(List.of(s.rooms.get("A2").center(),old.pa,old.pb,s.rooms.get("B2").center()));s.flags.add("archive_access");s.commandReceipts.put("0:trade",new Receipt(true,""));int supplies=s.supplies.get("parts");String campaign=s.campaignId;Object13Plan.migrate(s);assertEquals(2,s.layoutRevision);assertEquals(campaign,s.campaignId);assertEquals(71,a.hp);assertEquals(supplies,s.supplies.get("parts"));assertTrue(s.flags.contains("archive_access"));assertTrue(s.commandReceipts.containsKey("0:trade"));assertEquals(s.doors.get("D06").pa,a.path.get(1));assertEquals(s.doors.get("D06").pb,a.path.get(2));assertEquals(DoorStatus.CLOSED,s.doors.get("D06").status);assertTrue(s.rooms.get("A2").contains(a.x,a.y));}
    @Test void referenceValuesAreExplicitFixtureDataAndRemainDerived(){var s=VisualFixtures.referenceA();assertEquals("VISUAL_REFERENCE_A",s.scenario);assertEquals(28,s.actor(1).infection(),.001);assertEquals(38,s.actor(1).body.get("rightArm").infection);assertEquals(12,s.actor(0).infection(),.001);assertNotEquals(62,s.biomass());}
    @Test void researchDecisionRequiresActualLaboratoryAction(){var e=new GameEngine(WorldFactory.create("STORY"));for(var a:e.state.actors){a.connected=true;a.ready=true;}e.start();e.advance(60);for(int i=0;i<3;i++)assertTrue(e.command(i,new Packet("VOTE","sample-"+i,Map.of("cycle",1,"option","sample_goal"))).accepted());assertTrue(e.state.flags.contains("sample_goal"));assertFalse(e.state.flags.contains("hive_core_studied"));var a=e.state.actor(1);a.roomId="B7";var p=e.state.rooms.get("B7").center();a.x=p.x();a.y=p.y();e.state.rooms.get("B7").powered=true;assertTrue(e.command(1,new Packet("USE_OBJECT","lab-collect",Map.of("target","sample","action","COLLECT"))).accepted());e.advance(8.1);assertTrue(e.command(1,new Packet("USE_OBJECT","lab-analysis",Map.of("target","sample","action","ANALYSE"))).accepted());e.advance(10.1);assertTrue(e.state.flags.contains("hive_core_studied"));assertTrue(a.privateEvidence.contains("water_report"));}
}
